/bin/zsh -lc "cat > app.js <<'EOF'
function run({ state, request } = {}) {
  const fail = error => ({ state, ok: false, error });
  if ("'!request || typeof request !== '"'object') return fail('Invalid request');
  const { id, from, to, units, actor } = request;
  if (typeof id "'!== '"'string' || id.trim().length === 0) return fail('Invalid request id');
  if ("'!actor || actor.role !== '"'manager' || "'!Array.isArray(actor.stores)) {
    return fail('"'Manager permissions required');
  }
  if (typeof from "'!== '"'string' || typeof to "'!== '"'string' || from === to) {
    return fail('Distinct source and destination stores required');
  }
  if ("'!actor.stores.includes(from) || !actor.stores.includes(to)) {
    return fail('"'Access to both stores required');
  }
  if ("'!Number.isInteger(units) || units <= 0) return fail('"'Units must be a positive integer');
  if ("'!state || !state.stock || typeof state.stock !== '"'object' || Array.isArray(state.stock) ||
      "'!Array.isArray(state.done) ||
      !Object.values(state.stock).every(n => Number.isInteger(n) && n >= 0)) {
    return fail('"'Invalid inventory state');
  }
  if ("'!Object.prototype.hasOwnProperty.call(state.stock, from) ||
      !Object.prototype.hasOwnProperty.call(state.stock, to)) return fail('"'Unknown store');
  // Successful requests can be retried even after their original stock has moved.
  if (state.done.includes(id)) return { state, ok: true };
  if (state.stock[from] < units) return fail('Insufficient stock');
  const stock = { ...state.stock, [from]: state.stock[from] - units, [to]: state.stock[to] + units };
  if ("'!Number.isFinite(stock[to])) return fail('"'Destination stock overflow');
  return { state: { ...state, stock, done: [...state.done, id] }, ok: true };
}
module.exports = { run };
EOF
node <<'EOF'
const assert = require('node:assert/strict');
const {run} = require('./app');
const state = {stock:{a:5,b:0},done:[]};
const request = {id:'x',from:'a',to:'b',units:5,actor:{role:'manager',stores:['a','b']}};
const before = JSON.stringify(state);
const result = run({state,request});
assert.deepEqual(result,{state:{stock:{a:0,b:5},done:['x']},ok:true});
assert.equal(JSON.stringify(state),before);
assert.equal(run({state:result.state,request}).ok,true);
assert.deepEqual(run({state:result.state,request}).state,result.state);
for(const patch of [{id:''},{id:3},{units:0},{units:-1},{units:1.5},{units:6},{from:'b',to:'b'},{to:'c'},{actor:{role:'staff',stores:['a','b']}},{actor:{role:'manager',stores:['a']}}]) {
 const out=run({state,request:{...request,...patch}});
 assert.equal(out.ok,false); assert.equal(out.state,state); assert.ok(out.error); assert.equal(JSON.stringify(state),before);
}
assert.equal(run({state:result.state,request:{...request,actor:{role:'staff',stores:['a','b']}}}).ok,false);
assert.equal(run({state:result.state,request:{...request,units:0}}).ok,false);
console.log('Transfer, replay, authorization, invalid-input and immutability checks passed');
EOF
